const icons={spark:'<path d="m12 3 2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3Z"/>',closet:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M12 3v18M9 11v3m6-3v3"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.spark}</svg>`;
const UPPER_SAMPLE_IMAGE='assets/reference-commons-denim.jpg';
const itemSlots=[{id:'upper',label:'上衣',empty:'添加一件上衣'},{id:'bottom',label:'裤装',empty:'添加一件裤装'},{id:'shoes',label:'鞋类',empty:'添加一双鞋'}];
const state={view:'welcome',scenes:['日常通勤'],avoids:['太正式','显得沉闷'],styles:['简约日常'],change:'稍作尝试',changeAmount:50,intakeItems:{upper:null,bottom:null,shoes:null},generated:false,deckIndex:0,deckLimit:6,selected:null,owned:{},substitutions:{},revisions:{},saved:[],relaxed:[],feedback:{},personal:{'性别':'女性','年龄':'29'},note:'',budget:300,wardrobe:[],previewMode:'model'};

const genderOptions=['女性','男性','其他'];
const personalWheelFields=[
  {id:'height',key:'身高（cm）',title:'身高',unit:'cm',min:80,max:230,step:1,initial:'165'},
  {id:'weight',key:'体重（kg）',title:'体重',unit:'kg',min:20,max:250,step:.5,initial:'55'},
  {id:'body',key:'体型',title:'体型',choices:['暂不确定','直线型','梨形','苹果型','沙漏型','倒三角型']},
  {id:'reference',key:'风格参考',title:'风格参考',choices:styleOptions.map(option=>option.name)}
];
function personalWheelOptions(field){
  const values=field.choices||Array.from({length:Math.round((field.max-field.min)/field.step)+1},(_,i)=>String(field.min+i*field.step));
  return ['',...values];
}
function openPersonalPicker(id){
  const field=personalWheelFields.find(field=>field.id===id);if(!field)return;
  const options=personalWheelOptions(field),value=state.personal[field.key]||field.initial||'';
  const initial=Math.max(0,options.indexOf(value));
  modal('选择'+field.title,`<div class="personal-picker-content"><div class="personal-picker-toolbar"><p id="personal-picker-hint">上下滑动，点击完成后保存</p><button class="text-btn" onclick="selectPersonalWheel(0)">暂不填写</button></div><div class="age-wheel-frame"><div class="age-wheel-selection" aria-hidden="true"></div><div id="personal-wheel" class="age-wheel" data-field="${field.id}" role="listbox" aria-label="${field.title}" aria-describedby="personal-picker-hint" tabindex="0" onscroll="refreshPersonalWheel()" onkeydown="personalWheelKey(event)">${options.map((value,index)=>`<div id="personal-option-${index}" class="age-wheel-option" role="option" aria-selected="${index===initial}" onclick="selectPersonalWheel(${index})">${value?esc(value)+(field.unit?`<small aria-hidden="true">${field.unit}</small>`:''):'暂不填写'}</div>`).join('')}</div></div><div class="age-picker-actions"><button class="btn secondary" onclick="closeModal()">取消</button><button class="btn primary" onclick="confirmPersonalPicker()">完成</button></div></div>`);
  document.querySelector('#personal-'+id)?.setAttribute('aria-expanded','true');
  const wheel=document.querySelector('#personal-wheel');wheel.scrollTop=initial*44;refreshPersonalWheel();wheel.focus({preventScroll:true});
}
function personalWheelIndex(wheel){return Math.max(0,Math.min(wheel.children.length-1,Math.round(wheel.scrollTop/44)))}
function refreshPersonalWheel(){
  const wheel=document.querySelector('#personal-wheel');if(!wheel)return;
  const index=personalWheelIndex(wheel),active=wheel.querySelector('[aria-selected="true"]');
  if(active?.id!=='personal-option-'+index){active?.setAttribute('aria-selected','false');wheel.children[index].setAttribute('aria-selected','true')}
  wheel.setAttribute('aria-activedescendant','personal-option-'+index);
}
function selectPersonalWheel(index){
  const wheel=document.querySelector('#personal-wheel');if(!wheel)return;
  wheel.scrollTop=Math.max(0,Math.min(wheel.children.length-1,index))*44;refreshPersonalWheel();
}
function personalWheelKey(event){
  const wheel=event.currentTarget,index=personalWheelIndex(wheel);
  if(event.key==='Enter'){event.preventDefault();confirmPersonalPicker();return}
  const next={ArrowUp:index-1,ArrowDown:index+1,Home:0,End:wheel.children.length-1,PageUp:index-5,PageDown:index+5}[event.key];
  if(next===undefined)return;event.preventDefault();selectPersonalWheel(next);
}
function confirmPersonalPicker(){
  const wheel=document.querySelector('#personal-wheel');if(!wheel)return;
  const field=personalWheelFields.find(field=>field.id===wheel.dataset.field);if(!field)return;
  state.personal[field.key]=personalWheelOptions(field)[personalWheelIndex(wheel)];state.generated=false;
  const trigger=document.querySelector('#personal-'+field.id);
  if(trigger){trigger.innerHTML=personalChoiceValue(field);trigger.setAttribute('aria-label',field.key+'，'+(state.personal[field.key]||'未填写')+'，选填')}
  closeModal();trigger?.focus({preventScroll:true});
}
function profileSummary(personal){if(arguments.length===0)personal=state.personal;return [personal?.['性别'],personal?.['年龄']?personal['年龄']+' 岁':''].filter(Boolean).join(' · ')}
function setProfileGender(value){if(!genderOptions.includes(value))return;state.personal['性别']=value;state.generated=false;document.querySelector('#profile-error')?.setAttribute('hidden','');document.querySelectorAll('[name="profile-gender"]').forEach(input=>{input.checked=input.value===value})}
function setProfileAge(value){state.personal['年龄']=value.trim();state.generated=false;document.querySelector('#profile-age')?.removeAttribute('aria-invalid');document.querySelector('#profile-error')?.setAttribute('hidden','')}
function openAgePicker(){
  const initial=Math.max(0,Math.min(120,Number(state.personal['年龄'])||0));
  modal('选择年龄',`<div class="age-picker-content"><p class="age-picker-hint" id="age-picker-hint">上下滑动，选好后点击完成</p><div class="age-wheel-frame"><div class="age-wheel-selection" aria-hidden="true"></div><div id="age-wheel" class="age-wheel" role="listbox" aria-label="年龄" aria-describedby="age-picker-hint" tabindex="0" onscroll="refreshAgeWheel()" onkeydown="ageWheelKey(event)">${Array.from({length:121},(_,i)=>`<div id="age-option-${i}" class="age-wheel-option" role="option" aria-selected="${i===initial}" data-age="${i}" onclick="selectAgeWheel(${i})">${i?i+'<small aria-hidden="true">岁</small>':'暂不填写'}</div>`).join('')}</div></div><div class="age-picker-actions"><button class="btn secondary" onclick="closeModal()">取消</button><button class="btn primary" onclick="confirmAgePicker()">完成</button></div></div>`);
  document.querySelector('#profile-age')?.setAttribute('aria-expanded','true');
  const wheel=document.querySelector('#age-wheel');wheel.scrollTop=initial*44;refreshAgeWheel();wheel.focus({preventScroll:true});
}
function refreshAgeWheel(){
  const wheel=document.querySelector('#age-wheel');if(!wheel)return;
  const index=Math.max(0,Math.min(120,Math.round(wheel.scrollTop/44)));
  const active=wheel.querySelector('[aria-selected="true"]');if(active?.dataset.age!==String(index)){active?.setAttribute('aria-selected','false');document.querySelector('#age-option-'+index).setAttribute('aria-selected','true')}
  wheel.setAttribute('aria-activedescendant','age-option-'+index);
}
function selectAgeWheel(index){const wheel=document.querySelector('#age-wheel');if(!wheel)return;wheel.scrollTo({top:Math.max(0,Math.min(120,index))*44,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
function ageWheelKey(event){
  const wheel=event.currentTarget,index=Math.round(wheel.scrollTop/44);
  const next={ArrowUp:index-1,ArrowDown:index+1,Home:0,End:120,PageUp:index-5,PageDown:index+5}[event.key];
  if(event.key==='Enter'){event.preventDefault();confirmAgePicker();return}
  if(next===undefined)return;event.preventDefault();wheel.scrollTop=Math.max(0,Math.min(120,next))*44;refreshAgeWheel();
}
function confirmAgePicker(){
  const wheel=document.querySelector('#age-wheel');if(!wheel)return;
  const age=Math.max(0,Math.min(120,Math.round(wheel.scrollTop/44)));
  setProfileAge(age?String(age):'');closeModal();
  const trigger=document.querySelector('#profile-age');if(trigger){trigger.innerHTML=profileAgeLabel();trigger.setAttribute('aria-label','年龄，'+(age?age+' 岁':'暂不填写')+'，选填');trigger.focus({preventScroll:true})}
}
function validateProfile(){
  const age=state.personal['年龄']||'';
  const message=!genderOptions.includes(state.personal['性别'])?'请选择性别，再继续录入。':document.querySelector('#profile-age')?.validity?.badInput||age&&(!/^\d+$/.test(age)||Number(age)<1||Number(age)>120)?'年龄请填写 1–120 之间的整数，也可以留空。':'';
  if(!message)return true;
  if(state.view!=='intake'||state.intakeStep!==0){state.view='intake';state.intakeStep=0;render()}
  const error=document.querySelector('#profile-error');if(error){error.textContent=message;error.removeAttribute('hidden')}
  const target=document.querySelector(message.startsWith('年龄')?'#profile-age':'[name="profile-gender"]');if(message.startsWith('年龄'))target?.setAttribute('aria-invalid','true');target?.focus();toast(message);return false;
}

function sceneSummary(){return state.scenes.join('、')}
function stylePreferenceScore(o){return state.styles.reduce((score,name)=>score+Number(styleOptions.find(style=>style.name===name)?.outfits.includes(o.id)||false),0)}

function changeSummary(amount,label){if(arguments.length===0){amount=state.changeAmount;label=state.change}return Number.isFinite(amount)?label+' · '+amount+'%':label}
function changeDescription(amount=state.changeAmount){return amount<34?'沿用熟悉的基础款，少量调整搭配细节。':amount<67?'保留日常习惯，试一点新的颜色、比例或配饰。':'给新颜色、新轮廓和新搭配关系更多尝试空间。'}
function setChangeAmount(value){
  const number=Number(value);state.changeAmount=Number.isFinite(number)?Math.max(0,Math.min(100,Math.round(number))):50;
  state.change=state.changeAmount<34?'贴近日常':state.changeAmount<67?'稍作尝试':'大胆尝试';state.generated=false;
  const range=document.querySelector('#change-range');if(range){range.value=state.changeAmount;range.style.setProperty('--change-progress',state.changeAmount+'%');range.setAttribute('aria-valuetext',changeSummary())}
  const output=document.querySelector('#change-value');if(output)output.textContent=changeSummary();
  const description=document.querySelector('#change-description');if(description)description.textContent=changeDescription();
  const dock=document.querySelector('#avoid-dock-status');if(dock)dock.textContent='避开 '+state.avoids.length+' 种效果 · 尝试 '+state.changeAmount+'%';
}
function refreshAvoidSelection(){
  if(!document.querySelector('.avoid-grid'))return false;
  document.querySelectorAll('[data-avoid-value]').forEach(button=>{const selected=state.avoids.includes(button.dataset.avoidValue);button.setAttribute('aria-pressed',String(selected));button.querySelector('.choice-indicator').textContent=selected?'✓':'+'});
  document.querySelector('#avoid-count').textContent='已选 '+state.avoids.length+' 项 / 可不选';
  const dock=document.querySelector('#avoid-dock-status');if(dock)dock.textContent='避开 '+state.avoids.length+' 种效果 · 尝试 '+state.changeAmount+'%';
  return true;
}

const uploadVersions={upper:0,bottom:0,shoes:0};
function selectedItems(){return itemSlots.filter(slot=>state.intakeItems[slot.id]).map(slot=>({...state.intakeItems[slot.id],category:slot.id,label:slot.label}))}
function selectedItemName(category){const slot=itemSlots.find(slot=>slot.id===category);return state.intakeItems[category]?.name.trim()||slot?.label||'单品'}
function inputForItem(item,o){if(o?.ai)return item.itemId?o.inputItems.find(i=>i.itemId===item.itemId)||(state.aiWardrobe||[]).find(i=>i.itemId===item.itemId)||{name:item.name,itemId:item.itemId}:null;return state.intakeItems[item.id]||null}
function outfitInputItems(o){return o.ai?o.inputItems.map(item=>({...item,category:item.slot,label:itemSlots.find(slot=>slot.id===item.slot)?.label||item.slot})):selectedItems()}
function outfitItems(o){const ownUpper=state.intakeItems.upper&&!state.intakeItems.upper.sample;return [{id:'upper',name:'黑色宽松西装',role:'核心',tip:'参考图使用黑色西装外套；也可以回到录入页添加自己的上衣，再核对实际搭配。',color:'#292d28'},...o.items.map(i=>ownUpper&&i.id==='top'?{...i,role:'可选',tip:'参考图的内搭仅供选择。是否需要叠穿，请按你录入的上衣和实际穿着决定。'}:i)]}
function inputSummary(){return selectedItems().map(item=>selectedItemName(item.category)).join('、')}
function resetOutfitChoices(){state.deckIndex=0;state.deckLimit=6;state.generated=false;state.selected=null;state.owned={};state.substitutions={};state.revisions={};state.relaxed=[]}
function renameItem(category,value){if(!state.intakeItems[category])return;state.intakeItems[category].name=value;resetOutfitChoices();const heading=document.querySelector('#piece-name-'+category);if(heading)heading.textContent=selectedItemName(category)}
function removeItem(category){if(!itemSlots.some(slot=>slot.id===category))return;uploadVersions[category]++;state.intakeItems[category]=null;resetOutfitChoices();render();toast('已移除这件单品')}
try{const s=JSON.parse(localStorage.getItem('rewear-demo-v1')||'{}');state.saved=Array.isArray(s.saved)?s.saved:[];state.wardrobe=Array.isArray(s.wardrobe)?s.wardrobe:[]}catch{}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),3500)}
function go(v){if(v!==state.view)state.previousView=state.view;state.view=v;render();document.querySelector('#page-scroll')?.scrollTo({top:0,behavior:'auto'})}
function steps(n){return `<div id="workflow-progress-root" data-stage="${n}"></div>`}
function chipGroup(items,type,current){return `<div class="chips">${items.map(x=>`<button class="chip" data-focus="${type}-${x}" aria-pressed="${Array.isArray(current)?current.includes(x):current===x}" onclick="choose('${type}','${x}')">${x}</button>`).join('')}</div>`}
function choose(type,val){if(Array.isArray(state[type])){state[type]=state[type].includes(val)?state[type].filter(x=>x!==val):[...state[type],val]}else state[type]=val;if(type==='avoids'){state.generated=false;if(state.view==='intake'&&state.intakeStep===2&&refreshAvoidSelection())return}if(['scenes','styles'].includes(type)){state.generated=false;if(state.view==='intake'&&state.intakeStep===1&&refreshPreferenceSelection())return}render()}
function view(){return ({intake,results,build:buildView,saved:savedView,wardrobe:wardrobeView,finish:finishView}[state.view]||intake)()}
function startNewItem(){itemSlots.forEach(slot=>uploadVersions[slot.id]++);state.intakeItems={upper:null,bottom:null,shoes:null};state.intakeStep=0;resetOutfitChoices();go('intake')}
function useSample(){uploadVersions.upper++;state.intakeItems.upper={image:UPPER_SAMPLE_IMAGE,name:'黑色宽松西装',sample:true};resetOutfitChoices();toast('已选择黑色宽松西装示例，可以继续添加裤装或鞋类');render()}
function uploadItem(f,category='upper'){
  if(!f||!itemSlots.some(slot=>slot.id===category))return;
  if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>8*1024*1024)return toast('请选择 8 MB 以内的 JPG、PNG 或 WEBP 图片');
  const version=++uploadVersions[category],reader=new FileReader();
  reader.onload=()=>{if(uploadVersions[category]!==version)return;state.intakeItems[category]={image:reader.result,name:f.name.replace(/\.[^.]+$/,''),sample:false};resetOutfitChoices();render()};
  reader.onerror=()=>{if(uploadVersions[category]===version)toast('照片读取失败，请重新选择')};
  reader.readAsDataURL(f);
}
function startSearch(){if(!validateProfile())return;if(!selectedItems().length){toast('请至少录入一件上衣、裤装或鞋类');return}if(!state.scenes.length)return toast('请选择至少一个使用场景');if(!state.styles.length)return toast('请选择至少一种喜欢的风格');state.deckIndex=0;state.deckLimit=6;state.generated=true;go('results')}
function persist(){try{localStorage.setItem('rewear-demo-v1',JSON.stringify({saved:state.saved,wardrobe:state.wardrobe}));return true}catch{toast('浏览器未能保存记录，请导出清单留存');return false}}
function modal(title,body){const d=document.querySelector('#modal');d.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="close" onclick="closeModal()" aria-label="关闭弹窗">×</button></div>${body}`;d.setAttribute('aria-labelledby','modal-title');if(!d.open)d.showModal()}
function closeModal(){document.querySelector('#modal').close();state.personPhoto=null;document.querySelector('#profile-age')?.setAttribute('aria-expanded','false')}
document.querySelector('#modal').addEventListener('close',()=>{
  document.querySelector('#profile-age')?.setAttribute('aria-expanded','false');
  document.querySelectorAll('[data-personal-picker][aria-expanded="true"]').forEach(trigger=>{trigger.setAttribute('aria-expanded','false');trigger.focus({preventScroll:true})});
});
document.querySelector('#modal').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
function current(){return outfits.find(o=>o.id===state.selected)||outfits[0]}
function itemName(o,i){if(o.ai)return i.name;return inputForItem(i,o)?selectedItemName(i.id):state.substitutions[o.id+'-'+i.id]?.name||state.revisions[o.id]?.items?.[i.id]||i.name}
function itemTip(o,i){if(inputForItem(i,o))return '保留你录入的这件单品，结合实际试穿核对比例、舒适度与颜色。';const n=itemName(o,i);if(n===i.name)return i.tip;if(i.id==='shoes')return '选干净简洁的鞋型，留出脚趾空间，调整裤裙长度以免堆积。';if(i.id==='upper')return '检查肩线与上衣松量，需要叠穿时给内搭留出空间。';if(i.id==='top')return '保持领口平整与舒适松量，前摆轻收，避免与外套一起堆积。';if(i.id==='bottom')return '选择适合活动的松量，检查腰线与裤裙长度，保留整体比例。';return '优先沿用已有包袋，颜色与整套搭配保持协调。'}
function getStatus(o,i){return inputForItem(i,o)?'owned':state.owned[o.id+'-'+i.id]||(i.role==='可选'?'skip':'missing')}
function outfitList(o){return outfitItems(o).filter(i=>i.role==='核心').map(i=>itemName(o,i)).join(' / ')}
function userReason(o){const notes={'日常通勤':'日常通勤先保证舒适、整洁；严格着装要求仍需另外核对。','周末出门':'周末出门优先轻松、好活动。','朋友聚会':'朋友聚会可以加一点配饰，保持自在。','旅行':'旅行优先舒适鞋履与方便活动的下装。','看展':'看展优先方便久站和走动的鞋履，用简洁配饰点缀。','约会':'约会保留轻松感，让自己更自在。'};let s=state.scenes.map(scene=>notes[scene]||`用于${scene}，先保证活动自在。`).join('');s+='尝试程度：'+changeSummary()+'。';s+='选择的风格：'+state.styles.join('、')+'。本次保留：'+inputSummary()+'；其余单品按示例补齐。';return s+(state.change==='贴近日常'?'保持基础款与熟悉的中性色。':state.change==='大胆尝试'?'可以试试更鲜明的配饰，但整体关系保持不变。':'这次只改变一种搭配关系，其他部分保持熟悉。')}
function relaxModal(){modal('哪些条件可以放宽？',`<p class="muted small">保留当前场景和明确排斥的效果。演示中可改变参考筛选说明与排列顺序。</p><div class="check-list">${['西装面料','单品颜色','搭配方向'].map(x=>`<label><input type="checkbox" name="relax" value="${x}" ${state.relaxed.includes(x)?'checked':''}>${x}<small>${x==='西装面料'?'接受绒感、混纺等相似面料':x==='单品颜色'?'接受相近明度的基础色':'先看看不同的风格方向'}</small></label>`).join('')}</div><button class="btn wide" onclick="applyRelax()">按这些条件重新查看</button>`)}
function applyRelax(){state.deckIndex=0;state.relaxed=[...document.querySelectorAll('[name=relax]:checked')].map(e=>e.value);closeModal();render();toast('筛选条件已更新，演示使用已有参考池')}
function detail(id){const o=outfits.find(x=>x.id===id);modal(o.title,`<div class="detail-hero"><img src="${o.image}" alt="${esc(o.subtitle)}"><div><span class="eyebrow">${o.tag}</span><h3>${esc(o.subtitle)}</h3><p>${o.reason}</p><a class="credit" href="${o.sourceUrl||SOURCE}" target="_blank" rel="noopener noreferrer">查看原始照片与署名</a></div></div><div class="notice">${esc(o.difference)}<p>本次清单保留：${esc(inputSummary())}。参考照片未改变，上传单品尚未进行 AI 识别与匹配。</p></div><section class="analysis-section"><h3>为什么适合这次需求</h3><p>${userReason(o)}</p>${state.avoids.length?`<p>你不希望：${state.avoids.join('、')}。示例建议以基础内搭、简洁鞋履和适度留白来调整。</p>`:''}${state.note?`<p>补充要求：${esc(state.note)}。演示已记录，尚未接入自由需求理解。</p>`:''}${state.personal['体型']?`<p>已记录你的体型描述「${esc(state.personal['体型'])}」。演示尚未作身形分析，建议结合实际试穿调整松量。</p>`:''}</section><section class="analysis-section"><h3>这套用了什么</h3>${outfitItems(o).map(i=>`<div class="analysis-row"><span class="swatch"></span><div><strong>${esc(itemName(o,i))} <small class="muted">${i.role}</small></strong><p>${itemTip(o,i)}</p></div></div>`).join('')}</section><section class="analysis-section"><h3>可以替换，但保留这个关系</h3><p>${o.keep}</p><p>包袋可以直接沿用；鞋子可在干净的运动鞋、乐福鞋之间选择。</p></section><section class="analysis-section"><h3>这次先避开</h3><p>${o.avoid}</p></section>${state.revisions[o.id]?`<div class="notice">最近调整：${esc(state.revisions[o.id].explanation)}</div>`:''}<section class="analysis-section"><h3>换个场景穿 / 继续追问</h3><div class="chips"><button class="chip" onclick="answerQuestion('周末怎么穿','${o.id}')">周末怎么穿</button><button class="chip" onclick="answerQuestion('可以换运动鞋吗','${o.id}')">可以换运动鞋吗</button><button class="chip" onclick="answerQuestion('想更显利落','${o.id}')">想更显利落</button></div><div class="ask-row"><input id="question-input" type="text" placeholder="还有哪里拿不准？"><button class="btn small secondary" onclick="answerQuestion(document.querySelector('#question-input').value,'${o.id}')">追问</button></div><p id="answer" class="small muted" aria-live="polite"></p></section><button class="btn lime wide" onclick="closeModal();selectOutfit('${o.id}')">喜欢这个方向，看看衣柜怎么凑</button>`)}
function answerQuestion(q,id){if(!q.trim())return;const o=outfits.find(x=>x.id===id);document.querySelector('#answer').textContent='示例建议：'+(/鞋|运动/.test(q)?'可以换运动鞋。选择低帮、线条简洁的款式，裤脚不要大量堆在鞋面。':/周末|场景/.test(q)?'周末可将包袋换成帆布包，西装敞开穿，省去正式配饰。'+o.keep:/利落|身高|显高/.test(q)?'优先理顺比例：适度露出领口、前摆轻收、裤裙长度不拖地。具体效果还需要实际试穿。':'已记录你的问题「'+q+'」。此演示未接入自由问答，可以先参考：'+o.keep)}
function selectOutfit(id){if(!outfits.find(o=>o.id===id)?.ai)return toast('请先按当前要求生成 AI 方案');state.selected=id;go('build')}
function buildView(){const o=current(),missing=outfitItems(o).filter(i=>i.role==='核心'&&getStatus(o,i)==='missing'),ready=outfitItems(o).filter(i=>i.role==='核心'&&['owned','replaced'].includes(getStatus(o,i))).length;return `${steps(2)}<div class="page-heading"><div><h1>把这套搭配凑齐</h1><p>先看看有什么，再决定要不要买。</p></div><button class="btn secondary small" onclick="go('results')">比较其他方案</button></div><div class="build-layout"><aside class="selected-look"><div class="look-photo"><img src="${o.image}" alt="所选方案参考"><span class="photo-label">${esc(o.subtitle)}</span></div><div class="look-description"><div class="eyebrow">YOUR PICK</div><h2>${esc(o.title)}</h2><p class="muted small">${esc(o.difference)}</p><button class="text-btn" onclick="detail('${o.id}')">重看搭配分析</button><div class="look-actions"><button class="btn secondary wide" onclick="reviseModal()">还是不像我，调一调</button><button class="btn secondary wide" onclick="previewModal()">${icon('spark')} 可选 · 看组合预览</button></div></div></aside><div><section class="panel checklist-panel"><div class="panel-head"><h2>这套的单品清单</h2><span class="pill">核心 ${ready} / ${outfitItems(o).filter(i=>i.role==='核心').length} 已有</span></div>${outfitInputItems(o).map(item=>`<div class="target-item"><img src="${item.image}" alt="已录入的${item.label}"><div><strong>${esc(item.name)}</strong><p class="small muted">${item.label} · 本次搭配保留</p></div><span class="have-badge">${icon('check')} 已录入 · 我已有</span></div>`).join('')}<p class="input-items-note">已录入的单品不计入购买缺口。需要更换时，回到录入页修改。</p><button class="text-btn" onclick="state.intakeStep=0;go('intake')">编辑本次单品</button>${outfitItems(o).filter(i=>!inputForItem(i,o)).map(i=>`<div class="closet-row"><div class="closet-item-title"><span class="swatch large">${i.id==='upper'?'衣':i.id==='top'?'内':i.id==='bottom'?'下':i.id==='shoes'?'鞋':'包'}</span><div><strong>${esc(itemName(o,i))}</strong><p class="small muted">${i.role==='核心'?'构成这套搭配的核心单品':'可选配饰，不买也可以'}</p></div></div><div class="status-actions"><button class="chip ${['owned','replaced'].includes(getStatus(o,i))?'selected':''}" onclick="setOwned('${i.id}','${['owned','replaced'].includes(getStatus(o,i))?'missing':'owned'}')">${getStatus(o,i)==='replaced'?'已用衣柜替换':'我有这件'}</button><button class="chip" onclick="replaceModal('${i.id}')">用其他衣服替换</button>${i.role==='可选'?`<button class="chip ${getStatus(o,i)==='skip'?'selected':''}" onclick="setOwned('${i.id}','skip')">先不需要</button>`:''}</div>${state.substitutions[o.id+'-'+i.id]?`<div class="replacement-result">${icon('check')} ${esc(state.substitutions[o.id+'-'+i.id].advice)}</div>`:''}</div>`).join('')}${state.revisions[o.id]?`<div class="notice">${esc(state.revisions[o.id].explanation)}</div>`:''}</section><section class="panel shopping-panel"><div class="panel-head"><div><h2>${missing.length?`还有 ${missing.length} 件核心单品待解决`:'核心单品已经齐了'}</h2><p class="small muted" style="margin-top:7px">${missing.length?'也可以继续找衣柜替代，不急着下单。':'这套不用再买。配饰按心情选就好。'}</p></div>${icon('closet')}</div>${missing.length?`<div class="budget"><label for="budget">每件预算上限</label><div>¥ <input id="budget" type="number" min="0" max="10000" value="${state.budget}" onchange="state.budget=Math.max(0,Math.min(10000,Number(this.value)||0));render()"></div></div><div class="shopping-list">${missing.map(i=>`<div><strong>${esc(itemName(o,i))}</strong><p class="small muted">${itemTip(o,i)}</p><div class="shop-row"><span class="price">预算 ≤ ¥${state.budget}</span><button class="text-btn" onclick="purchaseModal('${i.id}')">看选购标准与候选示例</button></div></div>`).join('')}</div>`:`<div class="ready-note">${icon('check')} 先穿一次，再决定是否需要添置。</div>`}</section><div class="completion-bar"><div><strong>${missing.length?'把缺口和替换方法一起记下来':'这套已经有办法实现了'}</strong><p class="small muted">${missing.length?`待补齐 ${missing.length} 件；保存后仍会明确标注。`:'可跳过预览，直接保存。'}</p></div><button class="btn lime" onclick="savePlan()">保存这套穿搭计划</button></div></div></div>`}
function setOwned(id,status){if(state.intakeItems[id])return;state.owned[state.selected+'-'+id]=status;if(status!=='replaced')delete state.substitutions[state.selected+'-'+id];render()}
const alternativeOptions={upper:['已有的黑色西装','灰色宽松外套','深色短外套'],top:['已有的白色 T 恤','浅灰色针织衫','蓝白条纹上衣'],bottom:['深蓝色直筒牛仔裤','灰色垂感阔腿裤','低对比中长半裙'],shoes:['已有的白色运动鞋','黑色平底乐福鞋','棕色平底鞋'],bag:['已有的帆布包','小号黑色肩包','棕色斜挎包']};
function replaceModal(id){if(state.intakeItems[id])return toast('请回到录入页修改这件单品');state.replaceId=id;state.replacePhoto=null;const i=outfitItems(current()).find(x=>x.id===id);modal('衣柜里的哪件可以替换？',`<p class="muted small">替换 ${esc(itemName(current(),i))}。先试一个已有衣物示例，也可以上传自己的照片。</p><div class="replacement-options">${alternativeOptions[id].map((x,j)=>`<label><input type="radio" name="alternative" value="${x}" ${j===0?'checked':''}><span>${x}</span></label>`).join('')}</div><label class="upload-small">${icon('upload')} 上传已有衣服（可选）<input type="file" accept="image/jpeg,image/png,image/webp" onchange="replacementUpload(this.files[0])"></label><div id="replace-photo"></div><label class="small">补充衣服描述<input id="replace-desc" type="text" placeholder="例如：宽松、浅灰、针织材质"></label><p class="subtle-note" style="margin:12px 0 18px">演示根据选项给出预设调整建议，不会识别上传照片。</p><button class="btn wide" onclick="evaluateReplacement()">看看怎么替换</button><div id="replacement-answer" aria-live="polite"></div>`)}
function readImage(f,cb){if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>8388608)return toast('请选择 8 MB 以内的 JPG、PNG 或 WEBP 图片');const r=new FileReader();r.onload=()=>cb(r.result);r.readAsDataURL(f)}
function replacementUpload(f){readImage(f,src=>{state.replacePhoto=src;document.querySelector('#replace-photo').innerHTML=`<img src="${src}" alt="你上传的替换衣物" class="uploaded-thumb">`})}
function evaluateReplacement(){const id=state.replaceId,name=document.querySelector('[name=alternative]:checked').value,desc=document.querySelector('#replace-desc').value.trim();state.replaceDraft={name,desc,advice:id==='upper'?'调整后可替换：外套敞开穿，检查肩线和内搭松量。':id==='top'?'调整后可替换：领口保持简洁，前摆轻收，减少上身堆积。':id==='bottom'?'调整后可替换：保留腰线，检查裤裙与鞋面的衔接。':id==='shoes'?'可以替换：鞋面保持简洁，调整裤脚长度，避免堆积。':'可以替换：不用为配饰专门购物，控制整套颜色数量。'};document.querySelector('#replacement-answer').innerHTML=`<div class="notice"><strong>示例评估 · ${esc(name)}</strong><p>${state.replaceDraft.advice}</p>${desc?`<p class="small">已记录描述「${esc(desc)}」，尚未作图片或材质识别。</p>`:''}</div><button class="btn lime wide" onclick="applyReplacement()">用这件替换，更新清单</button>`}
function applyReplacement(){if(state.intakeItems[state.replaceId])return;const k=state.selected+'-'+state.replaceId;state.substitutions[k]={...state.replaceDraft};state.owned[k]='replaced';if(!state.wardrobe.some(x=>x.name===state.replaceDraft.name))state.wardrobe.push({name:state.replaceDraft.name,type:state.replaceId});persist();closeModal();render();toast('已更新搭配清单与购买缺口')}
function purchaseModal(id){if(state.intakeItems[id])return;const o=current(),i=outfitItems(o).find(x=>x.id===id),name=itemName(current(),i);modal('补齐这一件就好',`<span class="pill">核心单品 · ${esc(name)}</span><h3 style="margin:22px 0 8px">先看这些标准</h3><p class="muted small">${itemTip(o,i)}</p><div class="product-demo"><div class="swatch product-swatch">${['upper','top'].includes(id)?'上装':id==='bottom'?'下装':'鞋履'}</div><div><div class="eyebrow">CANDIDATE EXAMPLE</div><h3>${esc(name)} · 基础款</h3><p class="small muted">候选商品位置演示，无真实库存和报价</p><strong>你的预算：¥${state.budget} / 件以内</strong></div></div><p class="small muted">先核对尺码、面料与退换条件。此版本提供选购方向和搜索入口，尚未接入具体商品推荐。</p><div class="modal-actions"><a class="btn secondary" target="_blank" rel="noopener noreferrer" href="https://s.taobao.com/search?q=${encodeURIComponent(name)}">去淘宝按条件找</a><button class="btn lime" onclick="markSourcing('${id}')">记入待补齐清单</button></div><p class="subtle-note">打开搜索不会购买。标记待补齐也不会把它计为“已有”。</p>`)}
function markSourcing(id){if(state.intakeItems[id])return;state.owned[state.selected+'-'+id]='missing';closeModal();toast('已保留在待补齐清单，买到后再标记「我有这件」');render()}
function reviseModal(){const o=current();modal('哪里不像你？把喜欢的部分留下。',`<div class="field"><div class="field-title">先保留你满意的部分</div><div class="check-inline">${outfitItems(o).filter(i=>i.role==='核心').map(i=>`<label><input name="keep" value="${i.id}" type="checkbox" ${inputForItem(i,o)?'checked disabled':i.id==='bottom'?'checked':''}>${i.id==='upper'?'上衣':i.id==='top'?'内搭':i.id==='bottom'?'下装':'鞋子'}${inputForItem(i,o)?' · 已录入':''}</label>`).join('')}</div></div><div class="field"><div class="field-title">你想改善什么？</div><div class="replacement-options">${['太正式了','颜色太沉闷','变化太大','不够利落'].map((x,j)=>`<label><input type="radio" name="revision-reason" value="${x}" ${j===0?'checked':''}>${x}</label>`).join('')}</div></div><label>也可以自由说说<textarea id="revision-text" placeholder="比如：喜欢裤子，但上半身还不够轻松"></textarea></label><p class="subtle-note" style="margin:12px 0">已录入的单品始终保留；演示会依据所选原因调整其余未锁定单品；自由描述将记录到方案中。</p><button class="btn wide" onclick="applyRevision()">保留喜欢的，调整这一套</button>`)}
function applyRevision(){const o=current(),locked=[...document.querySelectorAll('[name=keep]:checked')].map(e=>e.value),reason=document.querySelector('[name=revision-reason]:checked').value,free=document.querySelector('#revision-text').value.trim();const items={...(state.revisions[o.id]?.items||{})},changes=[];const targets=reason==='太正式了'?{top:'白色基础 T 恤',shoes:'简洁白色运动鞋'}:reason==='颜色太沉闷'?{top:'米白色圆领上衣',bottom:'浅蓝色直筒牛仔裤'}:reason==='变化太大'?{top:'白色基础 T 恤',bottom:'深蓝色直筒牛仔裤',shoes:'已有的白色运动鞋'}:{top:'合身圆领上衣',bottom:'利落直筒下装',shoes:'简洁平底鞋'};Object.entries(targets).forEach(([id,name])=>{if(!locked.includes(id)&&!state.intakeItems[id]){items[id]=name;changes.push(name);delete state.substitutions[o.id+'-'+id];state.owned[o.id+'-'+id]='missing'}});const keep=locked.map(id=>outfitItems(o).find(i=>i.id===id)).map(i=>itemName(o,i));const explanation=`针对「${reason}」，${keep.length?'保留'+keep.join('、')+'；':''}${changes.length?'调整为'+changes.join('、')+'。改动单品需重新核对衣柜。':'核心单品已全部保留，建议敞开外套、简化配饰。'}${free?'你的补充：'+free+'。':''}参考照片未改变，请以更新后的清单为准。`;state.revisions[o.id]={items,explanation,reason,free};closeModal();render();toast('已保留锁定单品，并更新调整说明')}
function previewModal(){const o=current();modal('看看整套是不是你的感觉',`<div class="segmented two">${['model','person'].map(m=>`<button class="segment" aria-pressed="${state.previewMode===m}" onclick="state.previewMode='${m}';previewModal()">${m==='model'?'模特 / 参考展示':'本人试穿入口'}</button>`).join('')}</div><div class="notice">${state.previewMode==='model'?'这里展示原始参考图与最终清单，不是 AI 试穿生成。替换后的单品不会自动出现在照片里。':'本人试穿尚未接入生成服务。可以体验上传与方案比较，照片仅保留在当前页面。'}</div>${state.previewMode==='person'?`<label class="upload-small">${icon('upload')} 上传本人照片<input type="file" accept="image/jpeg,image/png,image/webp" onchange="readImage(this.files[0],src=>{state.personPhoto=src;document.querySelector('#person-photo').innerHTML='<img class=person-img alt=你上传的原照片 src='+src+'><p class=small>本人原照 · 尚未生成试穿效果</p>'})"></label><div id="person-photo"></div>`:''}<div class="preview-compare">${(o.ai?rankedOutfits():outfits).map(x=>`<button class="preview-card ${o.id===x.id?'selected':''}" onclick="state.selected='${x.id}';previewModal();render()"><img src="${x.image}" alt="${esc(x.subtitle)}"><strong>${esc(x.subtitle)}</strong><small>${x.id===o.id?'当前方案':'切换此方案'}</small></button>`).join('')}</div><h3 style="margin-top:20px">当前实际清单</h3><p class="small muted">${outfitList(o)}</p><p class="subtle-note">预览无法验证真实尺码、版型和舒适度，最终仍需实际试穿。</p><button class="btn wide" style="margin-top:20px" onclick="closeModal();render()">回到这套的衣柜清单</button>`)}
function savePlan(){const o=current();const plan={id:Date.now().toString(),outfitId:o.id,title:o.title,date:new Date().toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'}),scene:sceneSummary(),scenes:[...state.scenes],styles:[...state.styles],change:state.change,changeAmount:state.changeAmount,avoids:[...state.avoids],personal:{...state.personal},note:state.note,relaxed:[...state.relaxed],matchScore:matchOutfit(o).percent,sourceUrl:o.sourceUrl||SOURCE,item:inputSummary(),inputItems:selectedItems().map(item=>({category:item.category,label:item.label,name:selectedItemName(item.category)})),items:outfitItems(o).map(i=>({name:itemName(o,i),status:getStatus(o,i),role:i.role,tip:state.substitutions[o.id+'-'+i.id]?.advice||itemTip(o,i)})),feedback:null};state.saved.unshift(plan);state.lastPlan=plan.id;persist();go('finish')}
function finishView(){const p=state.saved.find(x=>x.id===state.lastPlan)||state.saved[0];if(!p)return savedView();const o=p.outfit||outfits.find(x=>x.id===p.outfitId),missing=p.items.filter(i=>i.role==='核心'&&i.status==='missing');return `${steps(3)}<div class="finish-heading"><span class="success-icon">${icon('check')}</span><div class="eyebrow">ONE STEP CLOSER TO WEARING IT</div><h1>${missing.length?'喜欢的这套，已经有实现计划了。':'下一次出门，就穿这一套。'}</h1><p>${missing.length?`还差 ${missing.length} 件核心单品，替换方向和选购标准已记录。`:'核心单品已齐，搭配关系和替换方法也都记下来了。'}</p></div><div class="finish-card"><img src="${o.image}" alt="已保存方案参考"><div><span class="pill">${esc(p.scene)} · ${esc(changeSummary(p.changeAmount,p.change))}</span><h2>${esc(p.title)}</h2><p class="small muted">本次单品：${esc(p.item)}</p>${profileSummary(p.personal)?`<p class="small muted">个人信息：${esc(profileSummary(p.personal))}</p>`:''}<div class="final-list">${p.items.map(i=>`<div><span>${esc(i.name)}</span><strong class="${i.status==='missing'?'pending':''}">${{owned:'已有',replaced:'衣柜替换',missing:'待补齐',skip:'可不添置'}[i.status]}</strong></div>`).join('')}</div><div class="modal-actions"><button class="btn secondary" onclick="downloadPlan('${p.id}')">导出穿搭清单</button><button class="btn" onclick="feedbackModal('${p.id}')">记录实际穿着</button></div></div></div><p class="bottom-note">计划已保存于当前体验会话。真正的完成，是你把它穿出门，并且喜欢。</p><div style="text-align:center;margin-top:22px"><button class="text-btn" onclick="go('saved')">查看我的搭配记录</button></div>`}
function savedView(){return `<div class="page-heading"><div><div class="eyebrow">THE OUTFITS YOU WILL WEAR</div><h1>穿搭记录</h1><p>当前体验会话的穿搭计划与实际反馈。</p></div><button class="btn secondary small" onclick="startNewItem()">再搭一套</button></div>${state.saved.length?`<div class="saved-grid">${state.saved.map(p=>{const o=p.outfit||outfits.find(x=>x.id===p.outfitId)||outfits[0];return `<article class="saved-card"><img src="${o.image}" alt="${esc(p.title)}参考"><div><span class="eyebrow">${esc(p.date)} · ${esc(p.scene)}</span><h2>${esc(p.title)}</h2><p class="small muted">${esc(p.item)}</p><span class="pill ${p.feedback?.worn?'worn':''}">${p.feedback?(p.feedback.worn?'穿了 · '+esc(p.feedback.satisfaction):'还没穿 · '+esc(p.feedback.reason)):'还没有穿着反馈'}</span>${p.feedback?.note?`<p class="small muted">${esc(p.feedback.note)}</p>`:''}<div class="card-actions"><button class="btn secondary small" onclick="state.lastPlan='${p.id}';go('finish')">查看清单</button><button class="btn small" onclick="feedbackModal('${p.id}')">${p.feedback?'更新反馈':'穿了 / 还没穿'}</button></div></div></article>`}).join('')}</div><p class="bottom-note">AI 计划和确认的衣物保存在服务端，凭当前浏览器的体验会话访问。清除 Cookie 后无法找回此匿名会话。</p>`:`<div class="empty panel">${icon('heart')}<h2>把第一套能穿的搭配留下来</h2><p>选定方案、核对衣柜后，就会出现在这里。</p><button class="btn lime" onclick="go(state.generated?'results':'intake')">开始搭配</button></div>`}`}
function feedbackModal(id){state.feedbackId=id;const p=state.saved.find(x=>x.id===id);state.feedbackWorn=p.feedback?.worn??true;renderFeedbackModal()}
function renderFeedbackModal(){const p=state.saved.find(x=>x.id===state.feedbackId);modal('这套搭配，后来穿出门了吗？',`<p class="small muted">${esc(p.title)}</p><div class="segmented two" style="margin:20px 0"><button class="segment" aria-pressed="${state.feedbackWorn}" onclick="state.feedbackWorn=true;renderFeedbackModal()">穿了</button><button class="segment" aria-pressed="${!state.feedbackWorn}" onclick="state.feedbackWorn=false;renderFeedbackModal()">还没穿</button></div><div class="field-title">${state.feedbackWorn?'穿上之后，感觉怎么样？':'现在卡在哪一步？'}</div><div class="replacement-options">${(state.feedbackWorn?['满意，很像自己','还不错，想再调整','不太满意']:['还缺单品','还没遇到合适场景','搭配还是不像我','有点不敢穿出去']).map((x,j)=>`<label><input type="radio" name="wear-answer" value="${x}" ${j===0?'checked':''}>${x}</label>`).join('')}</div><textarea id="wear-note" placeholder="记下真实感受，下次搭配会更有方向（选填）">${esc(p.feedback?.note||'')}</textarea><button class="btn lime wide" style="margin-top:20px" onclick="saveFeedback()">保存穿着反馈</button>`)}
function saveFeedback(){const p=state.saved.find(x=>x.id===state.feedbackId),answer=document.querySelector('[name=wear-answer]:checked').value;p.feedback={worn:state.feedbackWorn,satisfaction:state.feedbackWorn?answer:null,reason:!state.feedbackWorn?answer:null,note:document.querySelector('#wear-note').value.trim()};persist();closeModal();go('saved');toast(state.feedbackWorn?'已记录这次真实穿着':'已记录阻碍，下次可以从这里继续')}
function wardrobeView(){return `<div class="page-heading"><div><div class="eyebrow">ALREADY YOURS</div><h1>我的衣柜</h1><p>在搭配中用过的替换衣物，会留在这里。</p></div><button class="btn secondary small" onclick="go(state.generated?'results':'intake')">回到搭配</button></div>${state.wardrobe.length?`<div class="wardrobe-grid">${state.wardrobe.map(x=>`<div class="panel"><span class="wardrobe-icon">${icon('closet')}</span><h3>${esc(x.name)}</h3><p class="small muted">已用于衣柜替换 · 本机记录</p></div>`).join('')}</div>`:`<div class="empty panel">${icon('closet')}<h2>不必先整理整座衣柜</h2><p>先选一套喜欢的方向，再把已有的衣服一件件放进来。</p><button class="btn lime" onclick="go(state.generated?'results':'intake')">去找喜欢的搭配</button></div>`}`}
function downloadPlan(id){const p=state.saved.find(x=>x.id===id);const text=`再穿 REWEAR · 穿搭清单\n${p.title}\n日期：${p.date}\n场景：${p.scene}\n尝试程度：${changeSummary(p.changeAmount,p.change)}\n这次避开：${p.avoids?.join("、")||"未记录"}\n风格：${p.styles?.join('、')||'未记录'}\n个人信息：${profileSummary(p.personal)||'未记录'}\n补充要求：${p.note||'未填写'}\n本次单品：${p.item}\n\n${p.items.map(i=>`${i.name} — ${{owned:'已有',replaced:'衣柜替换',missing:'待补齐',skip:'可不添置'}[i.status]}\n${i.tip}`).join('\n\n')}\n\n参考照片来源：${p.sourceUrl||SOURCE}\n${p.outfit?.ai?'AI 辅助建议；参考照片未经试穿合成，尺码和舒适度仍需实际核对。':'历史交互演示，建议为预设内容。'}`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/plain;charset=utf-8'}));a.download='再穿-穿搭清单.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function resetModal(){modal('清空本机演示记录？',`<p>这会删除当前浏览器中的 ${state.saved.length} 套穿搭计划、反馈和衣柜替换记录。</p><div class="modal-actions"><button class="btn secondary" onclick="closeModal()">保留记录</button><button class="btn" onclick="state.saved=[];state.wardrobe=[];persist();closeModal();render();toast('本机记录已清空')">确认清空</button></div>`)}
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_outfit_demo_state',description:'读取当前演示页面、已选方案、已有单品与待补齐清单，不修改数据。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({view:state.view,scene:sceneSummary(),scenes:[...state.scenes],styles:[...state.styles],avoids:[...state.avoids],change:state.change,changeAmount:state.changeAmount,personal:{...state.personal},selected:state.selected,inputItems:selectedItems().map(item=>({category:item.category,name:selectedItemName(item.category)})),items:state.selected?outfitItems(current()).map(i=>({name:itemName(current(),i),status:getStatus(current(),i)})):[],savedPlans:state.saved.length})});document.modelContext.registerTool({name:'select_demo_outfit',description:'选择预设方案之一并打开衣柜核对步骤，不保存最终计划。',inputSchema:{type:'object',properties:{outfitId:{type:'string',enum:outfits.map(o=>o.id)}},required:['outfitId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!outfits.some(o=>o.id===input.outfitId))throw new Error('Unknown outfitId');if(!state.generated)throw new Error('请先在页面完成单品和需求录入');selectOutfit(input.outfitId);return {selected:state.selected,view:state.view}}})}catch(e){console.info('WebMCP unavailable',e.message)}}
render();
